#include "zf_common_headfile.h"

int core0_main(void)
{
    cpu_interrupt_enable();

    // 1) 初始化IPS200屏幕（SPI版本）
    ips200_init(IPS200_TYPE_SPI);

    // 2) 先清屏并显示固定信息
    ips200_set_color(RGB565_RED, RGB565_WHITE);
    ips200_clear();
    ips200_show_string(10, 10, "IPS200 DEBUG");

    ips200_set_color(RGB565_BLUE, RGB565_WHITE);
    ips200_show_string(10, 30, "Init OK");

    uint32 tick = 0;
    uint16 x = 0;
    int16 dir = 1;

    while(1)
    {
        // 显示递增计数，确认字符刷新
        ips200_set_color(RGB565_BLACK, RGB565_WHITE);
        ips200_show_string(10, 60, "tick:");
        ips200_show_uint(60, 60, tick, 10);

        // 显示一个左右移动的点，确认图形刷新
        ips200_draw_point(x, 100, RGB565_GREEN);

        // 处理下一位置
        if(dir > 0)
        {
            if(x < (ips200_width_max - 1)) x++;
            else dir = -1;
        }
        else
        {
            if(x > 0) x--;
            else dir = 1;
        }

        // 简单清除上一帧轨迹（可选）
        // 不想留痕就打开下面两句
        // ips200_draw_point(x, 100, RGB565_GREEN);
        // ips200_draw_point((dir > 0) ? (x - 1) : (x + 1), 100, RGB565_WHITE);

        tick++;
        system_delay_ms(100);
    }
}
```

